/* Entity suggestions are separate from title matches; source IDs never merge by name. */
(function(root){
 const norm=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
 const creatorQuery=q=>String(q||'').replace(/^(?:studio|developer|publisher|director|artist|author|writer|composer)\s+/i,'').replace(/\s+(?:studio|studios)$/i,'').trim();
 const nameMatch=(name,q)=>norm(creatorQuery(name))===norm(creatorQuery(q));
 const company=r=>['igdb','tmdb_company'].includes(r.provider)||(r.provider==='vndb'&&r.id.startsWith('p'));
 function evidence(ref,records=[],works=[]){const linked=records.filter(m=>(m.credits||[]).some(c=>c.url===ref.url));const titles=[...new Map([...linked,...works].map(m=>[m.id,m])).values()];const votes=Math.max(0,...titles.map(m=>Math.min(5,Math.log10(1+Math.max(0,m.rating_count||0)))));return votes*1.6+Math.min(3,works.length/6)+Math.min(4,linked.length*.35)+(company(ref)?.2:ref.provider==='spotify'?.1:0);}
 const api={nameMatch,evidence,creatorQuery};if(typeof module==='object')module.exports=api;if(typeof document==='undefined')return;
 const section=document.createElement('section');section.className='creator-search';section.hidden=true;section.setAttribute('aria-label','Matching artists and studios');document.querySelector('#live-results').before(section);
 let key='',generation=0,timer,controller,candidates=[],works=new Map(),loading=false,failed=false,force=false;
 const lookupCache=new Map(),workCache=new Map();
 const labels={spotify:'Spotify artist',apple:'Apple Music artist',musicbrainz:'MusicBrainz artist',igdb:'Game studio',tmdb_company:'Film / animation studio',vndb:'Visual novel creator',tmdb:'Film / TV creator',mangaupdates:'Manga creator',openlibrary:'Author'};
 function accepts(r,kind,provider){if(provider&&r.provider!==provider&&!(provider==='tmdb'&&r.provider==='tmdb_company'))return false;if(!kind)return true;return ['album','track'].includes(kind)?['spotify','apple','musicbrainz'].includes(r.provider):kind==='game'?r.provider==='igdb':['anime','tv','movie'].includes(kind)?['tmdb','tmdb_company'].includes(r.provider):kind==='visual_novel'?r.provider==='vndb':kind==='manga'?r.provider==='mangaupdates':kind==='book'?r.provider==='openlibrary':false;}
 function ranked(){const records=[...liveRecords,...items.flatMap(x=>x.metadata?FolioIdentity.records(x.metadata):[])];return [...candidates].sort((a,b)=>evidence(b,records,works.get(b.provider+':'+b.id)||[])-evidence(a,records,works.get(a.provider+':'+a.id)||[]));}
 function knownFor(ref){const linked=liveRecords.filter(m=>(m.credits||[]).some(c=>c.url===ref.url));const rows=[...linked,...(works.get(ref.provider+':'+ref.id)||[])].sort((a,b)=>((b.search_priority||0)*3+Math.log1p(b.rating_count||0))-((a.search_priority||0)*3+Math.log1p(a.rating_count||0)));return [...new Set(rows.map(m=>m.title))].slice(0,2).join(' · ');}
 function paint(){if(section.hidden)return;const rows=ranked().slice(0,4);section.setAttribute('aria-busy',String(loading));section.innerHTML=`<div class="creator-search-heading"><h2>Artists & studios</h2><span role="status">${loading?'Checking creator catalogs…':failed?'Some creator catalogs are unavailable.':rows.length?'Open a creator to explore their works.':'No exact creator matches; title results are below.'}</span>${failed?'<button type="button" class="creator-search-retry">Retry creator lookup</button>':''}</div><div class="creator-search-rows">${rows.map(r=>`<button type="button" class="creator-chip creator-search-choice" data-creator-name="${esc(r.name)}" data-creator-url="${esc(r.url)}"><strong>${esc(r.name)}</strong><small>${esc(labels[r.provider]||r.provider)}</small>${knownFor(r)?`<small class="creator-search-example">${esc(knownFor(r))}</small>`:''}<span>Explore works →</span></button>`).join('')}</div>`;const retry=section.querySelector('.creator-search-retry');if(retry)retry.onclick=()=>{force=true;key='';queue();};document.dispatchEvent(new CustomEvent('folio:creator-suggestions',{detail:{query:liveQuery}}));}
 async function find(q,kind,provider,current){controller?.abort();controller=new AbortController();try{const cacheKey=norm(creatorQuery(q)),cached=lookupCache.get(cacheKey);let data=!force&&cached&&Date.now()-cached.time<120000?cached.data:await metadataGet('creators/find?q='+encodeURIComponent(creatorQuery(q)),controller.signal,force);if(current!==generation)return;candidates=data.matches.filter(r=>nameMatch(r.name,q)&&accepts(r,kind,provider));if(!candidates.length&&data.providers?.some(p=>p.status==='unavailable')){data=await metadataGet('creators/find?q='+encodeURIComponent(creatorQuery(q)),controller.signal);if(current!==generation)return;candidates=data.matches.filter(r=>nameMatch(r.name,q)&&accepts(r,kind,provider));}failed=data.providers?.some(p=>p.status==='unavailable')||false;if(candidates.length){lookupCache.set(cacheKey,{time:Date.now(),data});while(lookupCache.size>32)lookupCache.delete(lookupCache.keys().next().value);}for(const r of candidates){const cachedWorks=workCache.get(r.provider+':'+r.id);if(!force&&cachedWorks&&Date.now()-cachedWorks.time<120000)works.set(r.provider+':'+r.id,cachedWorks.rows);}paint();const checks=ranked().slice(0,4).filter(r=>force||!works.has(r.provider+':'+r.id));await Promise.allSettled(checks.map(async r=>{try{const data=await metadataGet(`creators/${r.provider}/${encodeURIComponent(r.id)}/works?page=1`,controller.signal,force);if(current!==generation)return;works.set(r.provider+':'+r.id,data.results);workCache.set(r.provider+':'+r.id,{time:Date.now(),rows:data.results});while(workCache.size>32)workCache.delete(workCache.keys().next().value);paint();drawResults();}catch(e){if(e.name!=='AbortError'&&current===generation)failed=true;}}));}catch(e){if(current===generation&&e.name!=='AbortError')failed=true;}finally{if(current===generation){loading=false;force=false;section.hidden=!candidates.length&&!failed;paint();drawResults();}}}
 function queue(){const q=FolioSearch.intent(liveQuery).query,kind=document.querySelector('#live-kind').value||FolioSearch.intent(liveQuery).kind,provider=document.querySelector('#live-provider').value;const hide=q.length<3||q.split(/\s+/).length>5||/["“”]/.test(q)||['live-year','live-genre','live-platform','live-owned'].some(id=>document.getElementById(id).value);const next=hide?'':JSON.stringify([q,kind,provider]);section.hidden=hide||(!loading&&next===key&&!candidates.length&&!failed);if(next===key){paint();return;}key=next;generation++;clearTimeout(timer);controller?.abort();candidates=[];works=new Map();failed=false;if(!next)return;loading=true;paint();const current=generation;timer=setTimeout(()=>find(q,kind,provider,current),250);}
 const previous=drawResults;drawResults=function(){previous();queue();};
 document.addEventListener('folio:search-results',queue);document.addEventListener('change',e=>{if(e.target.closest('#live-filters'))queue();});
 document.querySelector('.search-refresh').addEventListener('click',()=>{force=true;key='';queue();});
 api.related=()=>{
  if(!key||section.hidden||!candidates.length||JSON.parse(key)[0]!==FolioSearch.intent(liveQuery).query)return [];
  const top=ranked()[0],rows=works.get(top.provider+':'+top.id)||[],score=evidence(top,liveRecords,rows);
  if(!rows.length||score<2)return [];
  const kind=document.querySelector('#live-kind').value||FolioSearch.intent(liveQuery).kind;
  return rows.filter(m=>!kind||FolioIdentity.matchesKind(m,kind)).map(m=>({...m,discovery_context:{query:liveQuery,name:top.name,url:top.url}}));
 };
 api.suggestions=q=>key&&JSON.parse(key)[0]===FolioSearch.intent(q).query?ranked().slice(0,3).map(r=>({q:r.name,creator:r,detail:(labels[r.provider]||r.provider)+(knownFor(r)?' · '+knownFor(r):'')})):[];
 root.FolioCreatorSearch=api;
})(globalThis);
